content.text:
{
  "name": "VDI PM5B功率计",
  "name_en": "VDI PM5B Power Meter",
  "manufacturer": "VDI",
  "description": "用于与 VDI PM5B 功率计通信，获取功率读数，并解析量程、状态与固件版本信息，适合实验中的射频或微波功率测量。",
  "description_en": "Communicates with the VDI PM5B power meter to obtain power readings and parse range, status, and firmware version information for RF or microwave power measurements in laboratory experiments.",
  "tag_hints": [
    "RF power measurement",
    "microwave power meter",
    "dBm conversion",
    "range-dependent reading conversion",
    "instrument query protocol",
    "firmware version readout"
  ],
  "actions": [
    {
      "action_name": "auto-padding",
      "description": "格式化发送给功率计的命令字符串，添加所需的填充与终止符。",
      "description_en": "Format a command string for the power meter by adding the required padding and termination characters."
    },
    {
      "action_name": "auto-reading_formula",
      "description": "根据所选量程和计数值换算功率读数，并按校准因子进行修正。",
      "description_en": "Convert a raw count value into a power reading based on the selected range, with calibration-factor correction."
    },
    {
      "action_name": "auto-decoderD",
      "description": "解析 D 类型数据包，提取功率读数与状态信息，并可换算为 dBm。",
      "description_en": "Decode a D packet to extract the power reading and status information, including conversion to dBm."
    },
    {
      "action_name": "auto-decoderVC",
      "description": "解析 VC 类型数据包，读取主固件和次固件版本信息。",
      "description_en": "Decode a VC packet to read the primary and secondary firmware version information."
    },
    {
      "action_name": "auto-query",
      "description": "向功率计发送查询命令并返回设备响应。",
      "description_en": "Send a query command to the power meter and return the device response."
    }
  ]
}

